# Synthetic data generated by Synthea — not real patient records.
"""Drive Synthea for a UAE population and turn its FHIR output into tidy tables.

Three public entry points:

* run_synthea_uae()   – shells out to synthea/run_synthea with configs/synthea_uae.properties
* parse_fhir_bundles() – FHIR R4 bundles -> long "clinical_events" DataFrame (+ parquet files)
* daily_aggregate()   – per-day signal counts used by the API and dashboard

This module is also loaded by the API (apps/api/routers/clinical.py) via importlib,
so it must import cleanly with only pandas/numpy/pyarrow installed and must not do
any work at import time.

All timestamps are UTC. Every dataset produced here is synthetic.
"""
from __future__ import annotations

import csv
import hashlib
import json
import os
import shutil
import subprocess
from concurrent.futures import ProcessPoolExecutor
from datetime import date, datetime, timedelta, timezone
from pathlib import Path
from typing import Iterable

import pandas as pd

SYNTHETIC_NOTICE = "Synthetic data generated by Synthea — not real patient records."

REPO_ROOT = Path(__file__).resolve().parents[3]
UAE_CONFIG = REPO_ROOT / "configs" / "synthea_uae.properties"
UAE_RESOURCES = REPO_ROOT / "configs" / "synthea" / "resources"
UAE_DEMOGRAPHICS = UAE_RESOURCES / "geography" / "demographics" / "uae_demographics.csv"
UAE_STATE = "United Arab Emirates"

EVENT_COLUMNS = ["patient_id", "event_type", "code", "display", "value", "unit", "event_time",
                 "event_end", "encounter_id", "reason_code", "encounter_class"]

# ---------------------------------------------------------------------------
# Code sets. Every SNOMED code below is either emitted by a stock Synthea module
# (grep synthea/src/main/resources/modules) or was checked active on the SNOMED CT
# International Edition via https://tx.fhir.org/r4/CodeSystem/$lookup (2026-11-12).
# ---------------------------------------------------------------------------

#: Respiratory diagnoses. An encounter counts as respiratory if its reasonCode, or
#: any Condition recorded at that encounter, is in this set.
RESPIRATORY_SNOMED: dict[str, str] = {
    "444814009": "Viral sinusitis",
    "36971009": "Sinusitis",
    "40055000": "Chronic sinusitis",
    "75498004": "Acute bacterial sinusitis",
    "195662009": "Acute viral pharyngitis",
    "43878008": "Streptococcal sore throat",
    "10509002": "Acute bronchitis",
    "233604007": "Pneumonia",
    "6142004": "Influenza",
    "840539006": "COVID-19",
    "840544004": "Suspected COVID-19",
    "195967001": "Asthma",
    "233678006": "Childhood asthma",
    "13645005": "Chronic obstructive pulmonary disease",
    "185086009": "Chronic obstructive bronchitis",
    "87433001": "Pulmonary emphysema",
    "65710008": "Acute respiratory failure",
    "67782005": "Acute respiratory distress syndrome",
    "389087006": "Hypoxemia",
    "409623005": "Respiratory insufficiency",
}

#: Heat-related presentations (emitted by configs/synthea uae_heat_illness module).
#: Heat exhaustion / heat stroke are intentionally absent: their SNOMED ids could not
#: be verified at build time. Add them here and in build_uae_modules.py once checked.
HEAT_SNOMED: dict[str, str] = {
    "34095006": "Dehydration",
    "240131006": "Rhabdomyolysis",
    "237840007": "Disorder of electrolytes",
    "89627008": "Hyponatremia",
    "14140009": "Hyperkalemia",
    "43339004": "Hypokalemia",
}

#: LOINC codes for cardiometabolic thresholds.
LOINC_HBA1C = "4548-4"                 # Hemoglobin A1c/Hemoglobin.total in Blood (%)
LOINC_GLUCOSE = {"1558-6",             # Fasting glucose [Mass/volume] in Serum or Plasma
                 "2345-7",             # Glucose [Mass/volume] in Serum or Plasma
                 "2339-0"}             # Glucose [Mass/volume] in Blood
LOINC_BP_PANEL = "85354-9"             # Blood pressure panel (components below)
LOINC_SYSTOLIC = "8480-6"
LOINC_DIASTOLIC = "8462-4"
HBA1C_THRESHOLD = 6.5                  # %   (> 6.5)
GLUCOSE_THRESHOLD = 126.0              # mg/dL (> 126). Synthea does not flag fasting
                                       # status, so all serum/blood glucose is used.
SYSTOLIC_THRESHOLD = 140.0             # mmHg (> 140)
DIASTOLIC_THRESHOLD = 90.0             # mmHg (> 90)


class SyntheaError(RuntimeError):
    """Synthea exited non-zero. The message carries the tail of its output."""


# ---------------------------------------------------------------------------
# 1. Run Synthea
# ---------------------------------------------------------------------------

def _synthea_dir(synthea_dir: Path | None) -> Path:
    d = Path(synthea_dir or os.environ.get("SYNTHEA_HOME") or REPO_ROOT / "synthea").resolve()
    if not (d / "run_synthea").exists():
        raise FileNotFoundError(f"run_synthea not found in {d} (set SYNTHEA_HOME)")
    return d


def install_uae_resources(synthea_dir: Path | None = None) -> Path:
    """Copy configs/synthea/resources/* (geography, providers, payers, modules) into
    the Synthea checkout's src/main/resources so they are on its classpath."""
    d = _synthea_dir(synthea_dir)
    shutil.copytree(UAE_RESOURCES, d / "src" / "main" / "resources", dirs_exist_ok=True)
    return d


def run_synthea_uae(population: int = 10000, seed: int = 42,
                    output_dir: Path = Path("data/raw/clinical"), *,
                    synthea_dir: Path | None = None,
                    reference_date: date | None = None,
                    timeout: float | None = None) -> Path:
    """Generate a synthetic UAE population and return the FHIR export directory.

    Simulation runs up to the end of ``reference_date`` (default: today, UTC), so a
    given (seed, reference_date) pair is reproducible and the current day is complete.
    """
    d = install_uae_resources(synthea_dir)
    output_dir = Path(output_dir).resolve()
    if output_dir.exists():
        # Synthea appends to existing export dirs; start clean for reproducibility.
        for sub in ("fhir", "csv", "metadata"):
            shutil.rmtree(output_dir / sub, ignore_errors=True)
    output_dir.mkdir(parents=True, exist_ok=True)

    ref = reference_date or datetime.now(timezone.utc).date()
    end = ref + timedelta(days=1)
    # -c MUST come first: Synthea applies options in order and the properties file
    # sets generate.default_population, which would otherwise override -p.
    cmd = ["./run_synthea",
           "-c", str(UAE_CONFIG),
           "-s", str(seed), "-cs", str(seed),
           "-p", str(population),
           "-r", ref.strftime("%Y%m%d"),
           "-e", end.strftime("%Y%m%d"),
           f"--exporter.baseDirectory={output_dir}/",
           UAE_STATE]
    env = {**os.environ, "TZ": "UTC"}
    proc = subprocess.run(cmd, cwd=d, env=env, capture_output=True, text=True, timeout=timeout)
    if proc.returncode != 0:
        tail = "\n".join((proc.stderr or proc.stdout or "").strip().splitlines()[-40:])
        raise SyntheaError(f"Synthea exited with code {proc.returncode}:\n{tail}")
    fhir = output_dir / "fhir"
    if not fhir.is_dir():
        raise SyntheaError(f"Synthea succeeded but no FHIR export at {fhir}")
    return fhir


# ---------------------------------------------------------------------------
# 2. Parse FHIR
# ---------------------------------------------------------------------------

def _to_utc(ts: str | None) -> pd.Timestamp | None:
    if not ts:
        return None
    t = pd.Timestamp(ts)
    return t.tz_localize("UTC") if t.tzinfo is None else t.tz_convert("UTC")


def _ref_id(ref: dict | None) -> str | None:
    if not ref or "reference" not in ref:
        return None
    r = ref["reference"]
    return r.split(":")[-1].split("/")[-1]


def _first_coding(cc: dict | None, system_hint: str | None = None) -> tuple[str | None, str | None]:
    if not cc:
        return None, None
    codings = cc.get("coding") or []
    for c in codings:
        if system_hint is None or system_hint in c.get("system", ""):
            return c.get("code"), c.get("display") or cc.get("text")
    if codings:
        return codings[0].get("code"), codings[0].get("display") or cc.get("text")
    return None, cc.get("text")


def _extension(resource: dict, url_suffix: str) -> dict | None:
    for ext in resource.get("extension", []) or []:
        if ext.get("url", "").endswith(url_suffix):
            return ext
    return None


def _us_core_text(resource: dict, url_suffix: str) -> str | None:
    ext = _extension(resource, url_suffix)
    if not ext:
        return None
    for sub in ext.get("extension", []):
        if sub.get("url") == "text":
            return sub.get("valueString")
    return None


def _load_ethnicity_shares(path: Path = UAE_DEMOGRAPHICS) -> dict[str, dict[str, float]]:
    shares: dict[str, dict[str, float]] = {}
    if not path.exists():
        return shares
    with open(path) as f:
        for row in csv.DictReader(f):
            shares[row["NAME"]] = {k: float(row[k]) for k in
                                   ("EMIRATI", "SOUTH_ASIAN", "OTHER_ARAB", "WESTERN",
                                    "EAST_ASIAN", "AFRICAN")}
    return shares


# Synthea race (US Census) -> UAE ethnicity candidates. See build_uae_geography.py.
_RACE_TO_UAE = {
    "white": ("EMIRATI", "OTHER_ARAB", "WESTERN"),
    "asian": ("SOUTH_ASIAN", "EAST_ASIAN"),
    "black": ("AFRICAN",),
}
_NATIONAL_SHARES = {"EMIRATI": 0.12, "SOUTH_ASIAN": 0.60, "OTHER_ARAB": 0.15,
                    "WESTERN": 0.05, "EAST_ASIAN": 0.05, "AFRICAN": 0.03}


def assign_uae_ethnicity(patient_id: str, race: str | None, city: str | None,
                         shares: dict[str, dict[str, float]] | None = None) -> str:
    """Synthea only knows US census race. Recover a UAE ethnicity deterministically:
    restrict to the ethnicities that map to the patient's race, weight by the city's
    shares from uae_demographics.csv, and pick with a hash of the patient id."""
    r = (race or "").strip().lower()
    # Synthea's us-core-race text is e.g. "White", "Asian", "Black or African American".
    cands = next((v for k, v in _RACE_TO_UAE.items() if r.startswith(k)), None)
    if not cands:
        return "OTHER"
    if len(cands) == 1:
        return cands[0]
    city_shares = (shares or {}).get(city or "", _NATIONAL_SHARES)
    weights = [city_shares.get(c, 0.0) for c in cands]
    total = sum(weights) or 1.0
    u = int(hashlib.sha256(patient_id.encode()).hexdigest()[:12], 16) / float(16 ** 12)
    acc = 0.0
    for c, w in zip(cands, weights):
        acc += w / total
        if u < acc:
            return c
    return cands[-1]


def _age(birth: date, on: date) -> int:
    return on.year - birth.year - ((on.month, on.day) < (birth.month, birth.day))


def _parse_one(path: str) -> tuple[dict | None, list[tuple]]:
    """Parse a single patient bundle -> (patient row, event tuples)."""
    with open(path) as f:
        bundle = json.load(f)
    entries = bundle.get("entry") or []
    patient = None
    events: list[tuple] = []
    for e in entries:
        r = e.get("resource") or {}
        rt = r.get("resourceType")
        if rt == "Patient":
            patient = r
        elif rt == "Encounter":
            code, disp = _first_coding((r.get("type") or [None])[0], "snomed")
            reason, _ = _first_coding((r.get("reasonCode") or [None])[0], "snomed")
            period = r.get("period") or {}
            events.append(("encounter", code, disp, None, None,
                           period.get("start"), period.get("end"), r.get("id"),
                           reason, (r.get("class") or {}).get("code"), _ref_id(r.get("subject"))))
        elif rt == "Condition":
            code, disp = _first_coding(r.get("code"), "snomed")
            events.append(("condition", code, disp, None, None,
                           r.get("onsetDateTime") or r.get("recordedDate"),
                           r.get("abatementDateTime"), _ref_id(r.get("encounter")),
                           None, None, _ref_id(r.get("subject"))))
        elif rt == "Observation":
            t = r.get("effectiveDateTime") or (r.get("effectivePeriod") or {}).get("start")
            enc = _ref_id(r.get("encounter"))
            subj = _ref_id(r.get("subject"))
            code, disp = _first_coding(r.get("code"), "loinc")
            vq = r.get("valueQuantity")
            if vq is not None and vq.get("value") is not None:
                events.append(("observation", code, disp, float(vq["value"]), vq.get("unit"),
                               t, None, enc, None, None, subj))
            # Multi-component observations (e.g. BP panel 85354-9): one row per component.
            for comp in r.get("component") or []:
                cvq = comp.get("valueQuantity")
                if cvq is None or cvq.get("value") is None:
                    continue
                ccode, cdisp = _first_coding(comp.get("code"), "loinc")
                events.append(("observation", ccode, cdisp, float(cvq["value"]), cvq.get("unit"),
                               t, None, enc, None, None, subj))
    if patient is None:
        return None, []

    pid = patient["id"]
    addr = (patient.get("address") or [{}])[0]
    geo = _extension(addr, "geolocation") or {}
    latlon = {x.get("url"): x.get("valueDecimal") for x in geo.get("extension", [])}
    prow = {
        "patient_id": pid,
        "birth_date": patient.get("birthDate"),
        "deceased_time": patient.get("deceasedDateTime"),
        "gender": patient.get("gender"),
        "city": addr.get("city"),
        "lat": latlon.get("latitude"),
        "lon": latlon.get("longitude"),
        "race": _us_core_text(patient, "us-core-race"),
    }
    events = [(pid,) + ev[:-1] for ev in events]
    return prow, events


def _bundle_files(fhir_dir: Path) -> list[str]:
    return sorted(str(p) for p in Path(fhir_dir).glob("*.json")
                  if not p.name.startswith(("hospitalInformation", "practitionerInformation")))


def parse_fhir_bundles(fhir_dir: Path, *,
                       out_dir: Path | None = Path("data/processed/clinical"),
                       window_days: int | None = None,
                       as_of: date | None = None,
                       workers: int = 1) -> pd.DataFrame:
    """Parse every patient bundle in ``fhir_dir`` into a long clinical_events frame.

    Columns: patient_id, event_type (condition|observation|encounter), code, display,
    value, unit, event_time (UTC), plus event_end, encounter_id, reason_code,
    encounter_class which the aggregates need.

    ``window_days`` keeps encounters/observations from the last N days before
    ``as_of`` (default today UTC). Conditions are kept regardless of onset so that
    prevalence remains correct. Writes events.parquet and patients.parquet to
    ``out_dir`` unless it is None.
    """
    files = _bundle_files(fhir_dir)
    if not files:
        raise FileNotFoundError(f"no FHIR bundles in {fhir_dir}")
    if workers > 1:
        with ProcessPoolExecutor(max_workers=workers) as ex:
            results = list(ex.map(_parse_one, files, chunksize=32))
    else:
        results = [_parse_one(f) for f in files]

    patients = [p for p, _ in results if p is not None]
    rows = [ev for _, evs in results for ev in evs]
    events = pd.DataFrame(rows, columns=EVENT_COLUMNS)
    events["event_time"] = pd.to_datetime(events["event_time"], utc=True, format="ISO8601")
    events["event_end"] = pd.to_datetime(events["event_end"], utc=True, format="ISO8601")
    events["value"] = events["value"].astype("float64")
    for c in ("event_type", "unit", "encounter_class"):
        events[c] = events[c].astype("category")

    today = as_of or datetime.now(timezone.utc).date()
    if window_days is not None:
        cutoff = pd.Timestamp(today - timedelta(days=window_days), tz="UTC")
        keep = (events["event_type"] == "condition") | (events["event_time"] >= cutoff)
        events = events.loc[keep].reset_index(drop=True)

    pdf = build_patients_frame(patients, events, as_of=today)

    if out_dir is not None:
        write_parquets(events, pdf, Path(out_dir))
    return events


def build_patients_frame(patients: Iterable[dict], events: pd.DataFrame,
                         as_of: date | None = None) -> pd.DataFrame:
    today = as_of or datetime.now(timezone.utc).date()
    pdf = pd.DataFrame(list(patients), columns=["patient_id", "birth_date", "deceased_time",
                                                "gender", "city", "lat", "lon", "race"])
    bd = pd.to_datetime(pdf["birth_date"]).dt.date
    pdf["age"] = [_age(b, today) if pd.notna(b) else None for b in bd]
    pdf["deceased"] = pdf["deceased_time"].notna()
    pdf["deceased_time"] = pd.to_datetime(pdf["deceased_time"], utc=True, format="ISO8601")
    shares = _load_ethnicity_shares()
    pdf["ethnicity"] = [assign_uae_ethnicity(pid, race, city, shares)
                        for pid, race, city in zip(pdf["patient_id"], pdf["race"], pdf["city"])]
    # Active (not abated) condition count per patient — handy for summaries.
    cond = events[(events["event_type"] == "condition") & events["event_end"].isna()]
    n_active = cond.groupby("patient_id").size()
    pdf["active_condition_count"] = pdf["patient_id"].map(n_active).fillna(0).astype(int)
    return pdf


def write_parquets(events: pd.DataFrame, patients: pd.DataFrame, out_dir: Path) -> tuple[Path, Path]:
    """Write events.parquet / patients.parquet (zstd), tagging both as synthetic."""
    import pyarrow as pa
    import pyarrow.parquet as pq

    out_dir.mkdir(parents=True, exist_ok=True)
    meta = {b"synthetic_notice": SYNTHETIC_NOTICE.encode(),
            b"generated_at": datetime.now(timezone.utc).isoformat().encode(),
            b"generator": b"Synthea + sentinel-grid synthea_wrapper"}
    paths = []
    for name, df in (("events", events), ("patients", patients)):
        table = pa.Table.from_pandas(df, preserve_index=False)
        table = table.replace_schema_metadata({**(table.schema.metadata or {}), **meta})
        p = out_dir / f"{name}.parquet"
        pq.write_table(table, p, compression="zstd")
        paths.append(p)
    return paths[0], paths[1]


# ---------------------------------------------------------------------------
# 3. Aggregate
# ---------------------------------------------------------------------------

def _encounters_with_dx(events: pd.DataFrame, codes: set[str]) -> pd.Index:
    """Encounter ids whose reasonCode or any linked Condition code is in ``codes``."""
    enc = events[events["event_type"] == "encounter"]
    by_reason = enc.loc[enc["reason_code"].isin(codes), "encounter_id"]
    cond = events[(events["event_type"] == "condition") & events["code"].isin(codes)]
    return pd.Index(by_reason).union(pd.Index(cond["encounter_id"].dropna()))


def daily_aggregate(events_df: pd.DataFrame, since: date, until: date) -> pd.DataFrame:
    """Per-day (UTC) counts between ``since`` and ``until`` inclusive.

    Columns: date, respiratory_encounter_count, heat_related_encounter_count,
    cardiometabolic_event_count, any_encounter_count. Days with no events are 0.
    """
    if since > until:
        raise ValueError("since must be <= until")
    days = pd.date_range(since, until, freq="D").date
    out = pd.DataFrame({"date": days})
    ev = events_df
    if ev.empty:
        for c in ("respiratory_encounter_count", "heat_related_encounter_count",
                  "cardiometabolic_event_count", "any_encounter_count"):
            out[c] = 0
        return out

    day = ev["event_time"].dt.tz_convert("UTC").dt.date
    in_range = (day >= since) & (day <= until)

    enc_mask = (ev["event_type"] == "encounter") & in_range
    enc = pd.DataFrame({"encounter_id": ev.loc[enc_mask, "encounter_id"].values,
                        "date": day[enc_mask].values})
    resp_ids = _encounters_with_dx(ev, set(RESPIRATORY_SNOMED))
    heat_ids = _encounters_with_dx(ev, set(HEAT_SNOMED))

    def count(frame: pd.DataFrame) -> pd.Series:
        return frame.groupby("date").size()

    any_c = count(enc)
    resp_c = count(enc[enc["encounter_id"].isin(resp_ids)])
    heat_c = count(enc[enc["encounter_id"].isin(heat_ids)])

    obs = ev[(ev["event_type"] == "observation") & in_range].copy()
    obs["date"] = day[obs.index]
    a1c = obs[(obs["code"] == LOINC_HBA1C) & (obs["value"] > HBA1C_THRESHOLD)]
    glu = obs[obs["code"].isin(LOINC_GLUCOSE) & (obs["value"] > GLUCOSE_THRESHOLD)]
    # BP: pair systolic/diastolic recorded at the same instant for the same patient;
    # one reading counts once if either component is over threshold.
    bp = obs[obs["code"].isin([LOINC_SYSTOLIC, LOINC_DIASTOLIC])]
    if not bp.empty:
        wide = bp.pivot_table(index=["patient_id", "event_time", "date"], columns="code",
                              values="value", aggfunc="max", observed=True).reset_index()
        sys_ = wide.get(LOINC_SYSTOLIC, pd.Series(dtype=float))
        dia_ = wide.get(LOINC_DIASTOLIC, pd.Series(dtype=float))
        high_bp = wide[(sys_ > SYSTOLIC_THRESHOLD) | (dia_ > DIASTOLIC_THRESHOLD)]
    else:
        high_bp = pd.DataFrame(columns=["date"])
    cm_c = (count(a1c[["date"]]).add(count(glu[["date"]]), fill_value=0)
            .add(count(high_bp[["date"]]), fill_value=0))

    for col, s in (("respiratory_encounter_count", resp_c),
                   ("heat_related_encounter_count", heat_c),
                   ("cardiometabolic_event_count", cm_c),
                   ("any_encounter_count", any_c)):
        out[col] = out["date"].map(s).fillna(0).astype(int)
    return out


def load_events(path: Path) -> pd.DataFrame:
    return pd.read_parquet(path)
